=== FILE: credit_counter_props.sv ===
// Formal properties for credit_counter, written against interface_spec.md.
// Immediate assertions only (open Yosys front end): clocked if-guards and
// $past guarded by a first-cycle flag. No input assumptions are made.
`default_nettype none

module credit_counter_props #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .take   (take),
        .give   (give),
        .credits(credits),
        .avail  (avail),
        .full   (full),
        .err    (err)
    );

    // First-cycle flag for $past, and a flag that a reset edge has been seen.
    reg f_past_valid = 1'b0;
    reg f_rst_done   = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_rst_done <= 1'b1;
    end

    // Combinational properties.
    always @(*) begin
        // Helper invariant for induction: no reset can be seen before the first edge.
        if (!f_past_valid)
            assert(!f_rst_done);
        // [req:CC-RANGE] credits never above MAX once reset has been applied.
        if (f_rst_done)
            assert(credits <= MAX);
        // [req:CC-STATUS] avail and full follow credits with no clock edge.
        assert(avail == (credits != 8'd0));
        assert(full == (credits == MAX));
    end

    // Clocked properties: each describes the edge after the sampled inputs.
    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:CC-RESET]
            if (!$past(rst_n)) begin
                assert(credits == MAX);
                assert(!err);
            end
            if ($past(rst_n)) begin
                // [req:CC-ERR-STICKY]
                if ($past(err))
                    assert(err);
                // [req:CC-TAKE]
                if ($past(take) && !$past(give) && ($past(credits) != 8'd0)) begin
                    assert(credits == $past(credits) - 8'd1);
                    assert(err == $past(err));
                end
                // [req:CC-UNDERFLOW] [req:CC-RANGE] no wrap below zero
                if ($past(take) && !$past(give) && ($past(credits) == 8'd0)) begin
                    assert(credits == 8'd0);
                    assert(err);
                end
                // [req:CC-GIVE]
                if ($past(give) && !$past(take) && ($past(credits) < MAX)) begin
                    assert(credits == $past(credits) + 8'd1);
                    assert(err == $past(err));
                end
                // [req:CC-OVERFLOW]
                if ($past(give) && !$past(take) && ($past(credits) == MAX)) begin
                    assert(credits == MAX);
                    assert(err);
                end
                // [req:CC-BOTH] no change and nothing refused, at zero and at MAX too
                if ($past(take) && $past(give)) begin
                    assert(credits == $past(credits));
                    assert(err == $past(err));
                end
                // [req:CC-IDLE]
                if (!$past(take) && !$past(give)) begin
                    assert(credits == $past(credits));
                    assert(err == $past(err));
                end
            end
        end
    end

    // Scenario covers: legal post-reset scenarios the proof must still allow.
    always @(posedge clk) begin
        if (f_past_valid && $past(f_rst_done) && $past(rst_n)) begin
            // Underflow refusal at zero.
            cover($past(take) && !$past(give) && ($past(credits) == 8'd0) && err);
            // Overflow refusal at MAX.
            cover($past(give) && !$past(take) && ($past(credits) == MAX) && err);
            // Both at once, at zero and at MAX.
            cover($past(take) && $past(give) && ($past(credits) == 8'd0));
            cover($past(take) && $past(give) && ($past(credits) == MAX));
            // Error held across a later edge.
            cover($past(err) && err);
        end
        if (f_past_valid && $past(f_rst_done)) begin
            // A set error cleared by reset.
            cover($past(err) && !$past(rst_n) && !err);
        end
    end

    always @(*) begin
        // Empty and full states reached after reset.
        cover(f_rst_done && (credits == 8'd0) && !avail);
        cover(f_rst_done && full && (credits == MAX));
    end
endmodule

module credit_counter_formal (
    input wire       clk,
    input wire [2:0] rst_n,
    input wire [2:0] take,
    input wire [2:0] give
);
    // [req:CC-PARAM] smallest MAX, the default, and a non-power-of-two.
    credit_counter_props #(.MAX(1)) p_max1 (
        .clk(clk), .rst_n(rst_n[0]), .take(take[0]), .give(give[0])
    );
    credit_counter_props #(.MAX(4)) p_max4 (
        .clk(clk), .rst_n(rst_n[1]), .take(take[1]), .give(give[1])
    );
    credit_counter_props #(.MAX(5)) p_max5 (
        .clk(clk), .rst_n(rst_n[2]), .take(take[2]), .give(give[2])
    );
endmodule

`default_nettype wire
=== END FILE ===
